1	package com.example.lending.application.service;
2	
3	import com.example.lending.application.port.in.LoanBookUseCase;
4	import com.example.lending.application.port.out.CreditCheckPort;
5	import com.example.lending.application.port.out.LoadBookPort;
6	import com.example.lending.application.port.out.LoadLoanPort;
7	import com.example.lending.application.port.out.LoadMemberPort;
8	import com.example.lending.application.port.out.LoadReservationsPort;
9	import com.example.lending.application.port.out.SaveBookPort;
10	import com.example.lending.application.port.out.SaveLoanPort;
11	import com.example.lending.application.port.out.SaveReservationPort;
12	import com.example.lending.domain.Book;
13	import com.example.lending.domain.BookNotFoundException;
14	import com.example.lending.domain.CreditCheck;
15	import com.example.lending.domain.Loan;
16	import com.example.lending.domain.Member;
17	import com.example.lending.domain.MemberNotFoundException;
18	import com.example.lending.domain.ReservationQueue;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	import java.time.LocalDate;
23	
24	@Service
25	@Transactional
26	public class LoanBookService implements LoanBookUseCase {
27	
28	    private final LoadMemberPort loadMemberPort;
29	    private final LoadBookPort loadBookPort;
30	    private final SaveBookPort saveBookPort;
31	    private final LoadLoanPort loadLoanPort;
32	    private final SaveLoanPort saveLoanPort;
33	    private final LoadReservationsPort loadReservationsPort;
34	    private final SaveReservationPort saveReservationPort;
35	    private final CreditCheckPort creditCheckPort;
36	
37	    public LoanBookService(LoadMemberPort loadMemberPort, LoadBookPort loadBookPort, SaveBookPort saveBookPort,
38	                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
39	                           LoadReservationsPort loadReservationsPort, SaveReservationPort saveReservationPort,
40	                           CreditCheckPort creditCheckPort) {
41	        this.loadMemberPort = loadMemberPort;
42	        this.loadBookPort = loadBookPort;
43	        this.saveBookPort = saveBookPort;
44	        this.loadLoanPort = loadLoanPort;
45	        this.saveLoanPort = saveLoanPort;
46	        this.loadReservationsPort = loadReservationsPort;
47	        this.saveReservationPort = saveReservationPort;
48	        this.creditCheckPort = creditCheckPort;
49	    }
50	
51	    @Override
52	    public Loan loanBook(LoanBookCommand command) {
53	        Member member = loadMemberPort.loadMember(command.memberId())
54	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
55	        Book book = loadBookPort.loadBook(command.bookId())
56	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
57	        member.ensureCanBorrow(loadLoanPort.countActiveLoansByMemberId(member.getId()));
58	        book.ensureLoanable();
59	        ReservationQueue queue = new ReservationQueue(book.getId(),
60	                loadReservationsPort.loadActiveReservations(book.getId()));
61	        queue.ensureLoanableBy(member.getId());
62	        // 신용조회는 대출 가능 여부 검사를 모두 통과한 뒤에 한다. 거절돼도 책 상태는 바뀌지 않는다
63	        CreditCheck creditCheck = creditCheckPort.check(member.getId(), member.getName());
64	        creditCheck.ensureApproved(member.getId());
65	        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
66	        Loan loan = book.loanTo(member.getId(), loanedAt, creditCheck);
67	        saveBookPort.saveBook(book);
68	        saveLoanPort.saveLoan(loan);
69	        // 맨 앞 예약자가 빌린 것이므로 그 예약을 소진한다
70	        queue.front().ifPresent(reservation -> {
71	            reservation.fulfill();
72	            saveReservationPort.saveReservation(reservation);
73	        });
74	        return loan;
75	    }
76	}
